package scene;
import java.util.List;
import java.util.Objects;

public final class Formats {
    private Formats() {}
    private static List<String> children(List<String> values) { return List.copyOf(Objects.requireNonNull(values, "children")); }
    public static final class Plain implements Renderer {
        public String circle(String name, int radius) { return "circle(" + Graphic.name(name) + "," + Graphic.size(radius) + ")"; }
        public String box(String name, int width, int height) { return "box(" + Graphic.name(name) + "," + Graphic.size(width) + "x" + Graphic.size(height) + ")"; }
        public String group(List<String> values) { return "group[" + String.join(";", children(values)) + "]"; }
    }
    public static final class Compact implements Renderer {
        public String circle(String name, int radius) { return "C:" + Graphic.name(name) + ":" + Graphic.size(radius); }
        public String box(String name, int width, int height) { return "B:" + Graphic.name(name) + ":" + Graphic.size(width) + ":" + Graphic.size(height); }
        public String group(List<String> values) { return "G(" + String.join("|", children(values)) + ")"; }
    }
}

// Decorator: add one visible frame while preserving the wrapped Graphic contract.
package scene;
import java.util.Objects;

public final class Frame implements Graphic {
    private final Graphic wrapped;
    public Frame(Graphic wrapped) { this.wrapped = Objects.requireNonNull(wrapped, "wrapped"); }
    public Graphic wrapped() { return wrapped; }
    public String render() { return "[" + Objects.requireNonNull(wrapped.render(), "wrapped text") + "]"; }
}

// Flyweight: share immutable intrinsic glyph state within one bounded pool.
package scene;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

public final class GlyphPool {
    public enum Tone { INK, ACCENT }
    public record Glyph(char symbol, Tone tone) {
        public Glyph {
            Objects.requireNonNull(tone, "tone");
            if (symbol < 'A' || symbol > 'Z') throw new IllegalArgumentException("symbol must be A..Z");
        }
    }
    private record Key(char symbol, Tone tone) {}
    private final Map<Key, Glyph> pool = new HashMap<>();
    public int size() { return pool.size(); }
    public Glyph get(char symbol, Tone tone) {
        Objects.requireNonNull(tone, "tone");
        if (symbol < 'A' || symbol > 'Z') throw new IllegalArgumentException("symbol must be A..Z");
        return pool.computeIfAbsent(new Key(symbol, tone), key -> new Glyph(key.symbol(), key.tone()));
    }
}

package scene;
import java.util.Objects;

@FunctionalInterface
public interface Graphic {
    String render();
    static String name(String value) {
        Objects.requireNonNull(value, "name");
        if (!value.matches("[A-Za-z][A-Za-z0-9_]{0,19}")) throw new IllegalArgumentException("invalid name");
        return value;
    }
    static int size(int value) {
        if (value < 1 || value > 100) throw new IllegalArgumentException("size must be 1..100");
        return value;
    }
}

// Composite: an immutable child-list snapshot preserves child order and identity.
package scene;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;

public final class Group implements Graphic {
    private final Renderer renderer;
    private final List<Graphic> children;
    public Group(Renderer renderer, List<Graphic> children) {
        this.renderer = Objects.requireNonNull(renderer, "renderer");
        this.children = List.copyOf(Objects.requireNonNull(children, "children"));
    }
    public List<Graphic> children() { return children; }
    public String render() {
        List<String> rendered = new ArrayList<>();
        for (Graphic child : children) rendered.add(Objects.requireNonNull(child.render(), "child text"));
        return Objects.requireNonNull(renderer.group(rendered), "group text");
    }
}

// Proxy: load on first render, cache a successful product, and delegate each render.
package scene;
import java.util.Objects;
import java.util.function.Supplier;

public final class LazyGraphic implements Graphic {
    private final Supplier<? extends Graphic> loader;
    private Graphic loaded;
    public LazyGraphic(Supplier<? extends Graphic> loader) { this.loader = Objects.requireNonNull(loader, "loader"); }
    public boolean isLoaded() { return loaded != null; }
    public String render() {
        if (loaded == null) loaded = Objects.requireNonNull(loader.get(), "loaded graphic");
        return Objects.requireNonNull(loaded.render(), "rendered text");
    }
}

package scene;
import java.util.Objects;

public record Placement(GlyphPool.Glyph glyph, int x, int y) {
    public Placement {
        Objects.requireNonNull(glyph, "glyph");
        if (x < 0 || x > 1000 || y < 0 || y > 1000) throw new IllegalArgumentException("position must be 0..1000");
    }
    public String render() { return glyph.symbol() + ":" + glyph.tone() + "@" + x + "," + y; }
    public Placement shift(int dx, int dy) { return new Placement(glyph, Math.addExact(x, dx), Math.addExact(y, dy)); }
}

package scene;
import java.util.List;

/** Rendering notation varies independently of a graphic's geometry. */
public interface Renderer {
    String circle(String name, int radius);
    String box(String name, int width, int height);
    String group(List<String> renderedChildren);
}

